import { after } from "next/server";

async function logPageView() {
  // Simulate an analytics service call
  await fetch("https://httpbin.org/post", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ event: "page_view", path: "/", timestamp: Date.now() }),
  });
  console.log("[analytics] page view logged");
}

export default function Home() {
  after(logPageView);

  return (
    <main>
      <h1>Welcome</h1>
      <p>Page view is being logged in the background without blocking this response.</p>
    </main>
  );
}

